    this.color = ['#7b4b8a', '#2f6b6b', '#a3542f', '#5a6b8a', '#8a3f4f'][Math.floor(Math.random() * 5)];
  }

  knockDown() {
    this.alive = false;
    this.downTimer = 6 + Math.random() * 4; // respawns after a while
  }

  update(dt, world) {
    if (!this.alive) {
      this.downTimer -= dt;
      if (this.downTimer <= 0) {
        this.alive = true;
        this.state = 'idle';
        this.timer = 1;
      }
      return;
    }
    this.timer -= dt;
    if (this.timer <= 0) {
      if (this.state === 'idle') {
        const ang = Math.random() * Math.PI * 2;
        const dist = 80 + Math.random() * 220;
        const clamped = world.clamp(this.x + Math.cos(ang) * dist, this.y + Math.sin(ang) * dist);
        this.target = clamped;
        this.state = 'walk';
        this.timer = 6;
      } else {
        this.state = 'idle';
        this.timer = 1 + Math.random() * 3;
      }
    }
    if (this.state === 'walk' && this.target) {
      const dx = this.target.x - this.x, dy = this.target.y - this.y;
      const d = Math.hypot(dx, dy);
      if (d < 6) {
        this.state = 'idle';
        this.timer = 1 + Math.random() * 3;
      } else {
        this.angle = Math.atan2(dy, dx);
        const nx = this.x + (dx / d) * this.speed * dt;
        const ny = this.y + (dy / d) * this.speed * dt;
        if (!world.collidesCircle(nx, ny, this.radius)) {
          this.x = nx;
          this.y = ny;
        } else {
          this.state = 'idle';
          this.timer = 0.8;
        }
      }
    }
  }

  draw(ctx, cam) {
    const sx = this.x - cam.x, sy = this.y - cam.y;
    if (!this.alive) {
      ctx.save();
      ctx.translate(sx, sy);
      ctx.rotate(Math.PI / 2);
      ctx.fillStyle = this.color;
      ctx.fillRect(-this.radius, -4, this.radius * 2, 8);
